import 'package:udara_cli/core/core.dart';import 'package:udara_cli/services/config_service.dart';import 'package:udara_cli/services/slack_service.dart';class SetupCommand extends UdaraCommand {  SetupCommand() {    argParser.addFlag(      'reset',      abbr: 'r',      negatable: false,      help: 'Reset all configuration settings.',    );  }  @override  final String name = 'setup';  @override  final String description = 'Configure CLI settings including Slack notifications.';  @override  Future<void> run() async {    final reset = argResults!['reset'] as bool;    if (reset) {      await _resetConfiguration();      return;    }    print('🚀 Welcome to Udara CLI Setup!');    print('Let\'s configure your CLI preferences.\n');    await _configureSlack();    print('\n✅ Setup completed successfully!');    print('💡 You can run "udara_cli config" to view your current settings.');    print('💡 Run "udara_cli setup --reset" to reset all settings.');  }  Future<void> _configureSlack() async {    final currentlyConfigured = await ConfigService.isSlackConfigured();    if (currentlyConfigured) {      print('📱 Slack notifications are currently enabled.');      final reconfigure = _promptBool(        'Do you want to reconfigure Slack settings?',        defaultValue: false,      );      if (!reconfigure) {        print('Keeping existing Slack configuration.');        return;      }    }    final enableSlack = _promptBool(      '📱 Do you want to enable Slack notifications for build updates?',      defaultValue: false,    );    if (!enableSlack) {      if (currentlyConfigured) {        await ConfigService.removeSlackConfig();        print('✅ Slack notifications disabled.');      } else {        print('Slack notifications will remain disabled.');      }      return;    }    print('\n📋 To set up Slack notifications, you need to:');    print('1. Create a Slack App at https://api.slack.com/apps');    print('2. Add these bot token scopes: chat:write, files:write, channels:read');    print('3. Install the app to your workspace');    print('4. Copy the Bot User OAuth Token (starts with xoxb-)');    print('');    String? botToken;    while (botToken == null || botToken.isEmpty) {      stdout.write('🔑 Enter your Slack Bot Token: ');      botToken = stdin.readLineSync()?.trim();      if (botToken == null || botToken.isEmpty) {        print('❌ Bot token cannot be empty. Please try again.');        continue;      }      if (!botToken.startsWith('xoxb-')) {        print('⚠️ Warning: Bot token should start with "xoxb-"');        final proceed = _promptBool('Continue anyway?', defaultValue: false);        if (!proceed) {          botToken = null;          continue;        }      }      // Test the token      print('🧪 Testing Slack connection...');      final testResult = await _testSlackToken(botToken);      if (!testResult) {        print('❌ Failed to connect to Slack. Please check your token.');        botToken = null;        continue;      }    }    await ConfigService.setSlackBotToken(botToken);    print('✅ Slack notifications configured successfully!');    print('💡 You can specify channels per build using --slack-channel parameter');  }  Future<bool> _testSlackToken(String token) async {    try {      final slackService = SlackService(        botToken: token,        channel: '#general', // Just for testing      );      // Try to send a test message to validate the token      // We'll use the auth.test endpoint instead of sending a message      final response = await slackService.testConnection();      return response;    } catch (e) {      return false;    }  }  bool _promptBool(String question, {bool defaultValue = false}) {    final defaultText = defaultValue ? 'Y/n' : 'y/N';    while (true) {      stdout.write('$question ($defaultText): ');      final input = stdin.readLineSync()?.trim().toLowerCase();      if (input == null || input.isEmpty) {        return defaultValue;      }      if (input == 'y' || input == 'yes') {        return true;      } else if (input == 'n' || input == 'no') {        return false;      } else {        print('Please enter y/yes or n/no.');      }    }  }  Future<void> _resetConfiguration() async {    print('🔄 Resetting CLI configuration...');    final confirm = _promptBool(      '⚠️ This will remove all saved settings. Are you sure?',      defaultValue: false,    );    if (!confirm) {      print('Reset cancelled.');      return;    }    await ConfigService.removeSlackConfig();    print('✅ Configuration reset successfully!');    print('💡 Run "udara_cli setup" to reconfigure your settings.');  }}